using System;using System.IO;using System.Collections.Generic;using System.Reflection;using System.Diagnostics;using System.Drawing;using System.Windows.Forms;using System.Web.Script.Serialization;using Microsoft.Win32;
[assembly:AssemblyVersion("0.1.2.2")]
class UninstallForm:Form {
 const string ProductId="__PRODUCT_ID__",Entry="SteamSafe.exe";string folder;CheckBox erase=new CheckBox();Label status=new Label();Button remove=new Button();
 public UninstallForm(){folder=Path.GetDirectoryName(Assembly.GetExecutingAssembly().Location);Text="卸载 SteamSafe";ClientSize=new Size(650,330);Font=new Font("Microsoft YaHei UI",10);FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;StartPosition=FormStartPosition.CenterScreen;
  Controls.Add(new Label(){Text="卸载 SteamSafe",Font=new Font(Font.FontFamily,20,FontStyle.Bold),Location=new Point(25,25),AutoSize=true});Controls.Add(new Label(){Text="将移除本次安装、自启任务和属于本次安装的快捷方式。",Location=new Point(28,80),Size=new Size(590,35)});Controls.Add(new Label(){Text=folder,Location=new Point(28,120),Size=new Size(590,40)});
  erase.Text="同时删除设置、缓存和隔离备份（所有版本共享，不可恢复）";erase.SetBounds(28,169,590,32);erase.Checked=false;Controls.Add(erase);Controls.Add(new Label(){Text="默认保留隔离和恢复材料。卸载不会删除 Steam、游戏或存档。",Location=new Point(28,210),Size=new Size(590,35)});status.SetBounds(28,248,590,30);Controls.Add(status);remove.Text="卸载";remove.SetBounds(420,285,90,32);remove.Click+=delegate{RunUninstall();};Controls.Add(remove);var cancel=new Button(){Text="取消",Location=new Point(530,285),Size=new Size(90,32)};cancel.Click+=delegate{Close();};Controls.Add(cancel);
 }
 static string KeyPath{get{return @"SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\"+ProductId;}}
 static void RemoveLink(string link,string target){if(!File.Exists(link))return;SetupSecurity.NoLinks(link);dynamic shell=Activator.CreateInstance(Type.GetTypeFromProgID("WScript.Shell"));dynamic shortcut=shell.CreateShortcut(link);if(((string)shortcut.TargetPath).Equals(target,StringComparison.OrdinalIgnoreCase))File.Delete(link);}
 static void DeletePrivateData(string path){SetupSecurity.NoLinks(path);if(!Directory.Exists(path))return;SetupSecurity.ValidateAcl(path,false);var dirs=new List<string>();var files=new List<string>();Collect(path,path,dirs,files);foreach(string f in files)File.Delete(f);dirs.Sort((a,b)=>b.Length.CompareTo(a.Length));foreach(string d in dirs)Directory.Delete(d,false);Directory.Delete(path,false);}
 static void Collect(string root,string dir,List<string> dirs,List<string> files){SetupSecurity.NoLinks(dir);foreach(string file in Directory.GetFiles(dir)){SetupSecurity.Within(root,file.Substring(root.Length+1));files.Add(file);}foreach(string child in Directory.GetDirectories(dir)){SetupSecurity.NoLinks(child);dirs.Add(child);Collect(root,child,dirs,files);}}
 void RunUninstall(){try{SetupSecurity.Destination(folder);SetupSecurity.NoLinks(folder);SetupSecurity.ValidateAcl(folder,false);SetupSecurity.ParentPolicy(folder);
  string menu;using(var key=Registry.LocalMachine.OpenSubKey(KeyPath)){if(key==null||!folder.Equals((string)key.GetValue("InstallLocation"),StringComparison.OrdinalIgnoreCase))throw new Exception("卸载登记与当前目录不匹配，拒绝删除");menu=(string)key.GetValue("StartMenu","");}
  if(erase.Checked){using(var parent=Registry.LocalMachine.OpenSubKey(@"SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall")){foreach(string name in parent.GetSubKeyNames())if(name.StartsWith("SteamSafeBeta-")&&name!=ProductId)throw new Exception("仍登记有其他版本，不能删除共享备份。请保留数据或先卸载其他版本。");}if(MessageBox.Show(this,"确认永久删除所有设置、缓存与隔离备份？","删除私有数据",MessageBoxButtons.YesNo,MessageBoxIcon.Warning)!=DialogResult.Yes)return;}
  remove.Enabled=false;status.Text="正在卸载…";Application.DoEvents();string exe=Path.Combine(folder,Entry);
  foreach(var p in Process.GetProcessesByName("SteamSafe")){try{if(p.MainModule.FileName.Equals(exe,StringComparison.OrdinalIgnoreCase)){p.Kill();p.WaitForExit(5000);}}catch(InvalidOperationException){}}
  dynamic service=Activator.CreateInstance(Type.GetTypeFromProgID("Schedule.Service"));service.Connect();dynamic tasks=service.GetFolder("\\");try{dynamic task=tasks.GetTask("SteamSafeBeta");foreach(dynamic action in task.Definition.Actions)if(((string)action.Path).Equals(exe,StringComparison.OrdinalIgnoreCase)){tasks.DeleteTask("SteamSafeBeta",0);break;}}catch(System.Runtime.InteropServices.COMException e){if(e.ErrorCode!=unchecked((int)0x80070002))throw;}
  RemoveLink(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonDesktopDirectory),"SteamSafe Beta.lnk"),exe);
  string expectedMenu=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonPrograms),"SteamSafe Beta",ProductId);if(menu.Equals(expectedMenu,StringComparison.OrdinalIgnoreCase)){RemoveLink(Path.Combine(menu,"SteamSafe.lnk"),exe);RemoveLink(Path.Combine(menu,"卸载 SteamSafe.lnk"),Path.Combine(folder,"Uninstall.exe"));if(Directory.Exists(menu)&&Directory.GetFileSystemEntries(menu).Length==0)Directory.Delete(menu,false);}
  var serializer=new JavaScriptSerializer();serializer.MaxJsonLength=8*1024*1024;var envelope=serializer.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(folder,"release-manifest.json")));var payload=(Dictionary<string,object>)envelope["payload"];var manifest=(Dictionary<string,object>)payload["files"];var dirs=new HashSet<string>(StringComparer.OrdinalIgnoreCase);
  foreach(string relative in manifest.Keys){string target=SetupSecurity.Within(folder,relative);if(relative.Equals("Uninstall.exe",StringComparison.OrdinalIgnoreCase))continue;string dir=Path.GetDirectoryName(target);while(dir.StartsWith(folder+"\\",StringComparison.OrdinalIgnoreCase)){dirs.Add(dir);dir=Path.GetDirectoryName(dir);}if(File.Exists(target))File.Delete(target);}
  string index=SetupSecurity.Within(folder,"release-manifest.json");if(File.Exists(index))File.Delete(index);var ordered=new List<string>(dirs);ordered.Sort((a,b)=>b.Length.CompareTo(a.Length));foreach(string d in ordered)if(Directory.Exists(d)&&Directory.GetFileSystemEntries(d).Length==0)Directory.Delete(d,false);
  if(erase.Checked)DeletePrivateData(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData),"SteamSafeBeta-v0.1.2"));
  Registry.LocalMachine.DeleteSubKeyTree(KeyPath,false);
  // No cmd /c deletion script. Windows removes the running uninstaller at reboot.
  if(!MoveFileEx(Path.Combine(folder,"Uninstall.exe"),null,4))throw new Exception("无法登记卸载器重启清理");if(Directory.GetFileSystemEntries(folder).Length==1)MoveFileEx(folder,null,4);
  status.Text="卸载完成";MessageBox.Show(this,"程序已卸载。卸载器及空目录将在重启后清理；未勾选的数据继续保留。","SteamSafe");Close();
 }catch(Exception e){remove.Enabled=true;status.Text="卸载未完成";MessageBox.Show(this,e.Message,"卸载未完成",MessageBoxButtons.OK,MessageBoxIcon.Error);}}
 [System.Runtime.InteropServices.DllImport("kernel32.dll",CharSet=System.Runtime.InteropServices.CharSet.Unicode,SetLastError=true)]static extern bool MoveFileEx(string existing,string next,int flags);
 [STAThread]static int Main(string[] args){try{SetupSecurity.CheckSelf();Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);using(var f=new UninstallForm()){if(args.Length==2&&args[0]=="--ui-smoke"){f.Show();f.PerformLayout();Application.DoEvents();IntPtr handle=f.Handle;using(var image=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(image,new Rectangle(0,0,f.Width,f.Height));image.Save(args[1]);}return 0;}Application.Run(f);}return 0;}catch(Exception e){if(args.Length>0){Console.Error.WriteLine(e.Message);return 1;}MessageBox.Show(e.Message,"卸载器验证失败",MessageBoxButtons.OK,MessageBoxIcon.Error);return 1;}}
}
